using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows.Forms;
internal static partial class Program {
 internal static EventWaitHandle ActivationSignal;
 internal static void RunSingleInstance(string[] args){bool fresh;using(var mutex=new Mutex(true,@"Local\MonEspaceNative-"+Environment.UserName,out fresh)){if(!fresh){try{using(var signal=EventWaitHandle.OpenExisting(@"Local\MonEspaceActivate-"+Environment.UserName))signal.Set();}catch(WaitHandleCannotBeOpenedException){MessageBox.Show("Mon espace est en cours de démarrage. Retrouvez son icône près de l’horloge.","Mon espace");}return;}using(ActivationSignal=new EventWaitHandle(false,EventResetMode.AutoReset,@"Local\MonEspaceActivate-"+Environment.UserName)){Application.Run(new MainForm(args.Contains("--startup")));ActivationSignal=null;}}}
}
internal sealed partial class MainForm {
 bool exitRequested,trayHintShown;
 internal static bool HideOnClose(bool preference,bool trayReady,bool force,bool preview,CloseReason reason){return preference&&trayReady&&!force&&!preview&&reason==CloseReason.UserClosing;}
 internal bool InterceptClose(FormClosingEventArgs e){if(!HideOnClose(store.Value.settings.CloseToTray,remindersIcon!=null,exitRequested,rendering,e.CloseReason))return false;if(dirty&&!Save()){e.Cancel=true;return true;}e.Cancel=true;Hide();if(!trayHintShown){trayHintShown=true;try{remindersIcon.ShowBalloonTip(5000,"Mon espace reste actif","Rappels et capture rapide restent disponibles. Double-cliquez sur l’icône pour rouvrir, ou choisissez Quitter pour arrêter.",ToolTipIcon.Info);}catch{}}return true;}
 internal void RequestQuit(){exitRequested=true;Close();if(!IsDisposed)exitRequested=false;}
 internal void ExportComplete(){if(modern.IsAttachmentBusy||modern.IsAutoBackupBusy){MessageBox.Show("Attendez la fin de la copie des fichiers.");return;}using(var picker=new SaveFileDialog{Title="Sauvegarder tout mon espace",Filter="Sauvegarde complète Mon espace|*.mespace",DefaultExt="mespace",FileName="Mon_espace-complet-"+DateTime.Now.ToString("yyyy-MM-dd")+".mespace"})if(picker.ShowDialog(this)==DialogResult.OK)try{FullBackup.Export(store,picker.FileName);notice.Text="Sauvegarde complète enregistrée.";MessageBox.Show("Votre sauvegarde contient les données, les réglages, les pièces jointes et votre MP3 si présent. Les dossiers épinglés restent des raccourcis : leur contenu n’est pas copié.","Sauvegarde complète");}catch(Exception ex){NotificationCenter.Incident(store.Value,"backup",DateTime.Today.ToString("yyyyMMdd"),"Sauvegarde complète échouée",ex.Message);try{store.Save();}catch{}modern.RefreshNoticeBadge();MessageBox.Show(ex.Message,"Sauvegarde impossible");}}
 internal void RestoreComplete(){if(modern.IsAttachmentBusy||modern.IsAutoBackupBusy){MessageBox.Show("Attendez la fin de la copie des fichiers.");return;}using(var picker=new OpenFileDialog{Title="Restaurer une sauvegarde complète",Filter="Sauvegarde complète Mon espace|*.mespace"})if(picker.ShowDialog(this)==DialogResult.OK)try{using(var plan=FullBackup.Prepare(store,picker.FileName)){string summary="Cette sauvegarde contient "+plan.Data.tasks.Count+" tâche(s), "+plan.Data.pages.Count+" page(s) et "+plan.Data.events.Count+" rendez-vous.\n\nElle remplacera les données et réglages de cet espace. Une copie complète de l’espace actuel sera conservée sur ce PC."+(plan.MissingFiles>0?"\n\nAttention : "+plan.MissingFiles+" pièce(s) jointe(s) sont absentes de cette sauvegarde.":"")+"\n\nRestaurer cet espace ?";if(MessageBox.Show(summary,"Restaurer Mon espace",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;modern.CancelGoogle();modern.CancelModeLaunch();Stop();string previous=FullBackup.Commit(store,plan);Theme.Gold=System.Drawing.ColorTranslator.FromHtml(store.Value.settings.Accent);Text=store.Value.settings.AppTitle;UpdateCaptureHotkey();modern.ResetAfterRestore();notice.Text="Espace restauré.";MessageBox.Show("Restauration terminée. Votre espace précédent est conservé ici :\n\n"+previous,"Mon espace");}}catch(Exception ex){MessageBox.Show(ex.Message,"Restauration impossible");}}
 internal static void TestTray(){if(!HideOnClose(true,true,false,false,CloseReason.UserClosing)||HideOnClose(true,true,true,false,CloseReason.UserClosing)||HideOnClose(true,true,false,false,CloseReason.WindowsShutDown)||HideOnClose(false,true,false,false,CloseReason.UserClosing)||HideOnClose(true,false,false,false,CloseReason.UserClosing)||HideOnClose(true,true,false,true,CloseReason.UserClosing))throw new Exception("Fermeture près de l’horloge invalide.");}
}
internal sealed partial class ModernWorkspace {
 void BackupSettings(System.Windows.Controls.StackPanel body){body.Children.Add(Btn("Configurer les sauvegardes automatiques",delegate{Go("Sauvegardes automatiques");},true));var tray=new System.Windows.Controls.CheckBox{Content="Fermer la fenêtre près de l’horloge et rester actif",IsChecked=store.Value.settings.CloseToTray,Margin=new System.Windows.Thickness(0,0,0,10)};tray.Click+=delegate{store.Value.settings.CloseToTray=tray.IsChecked==true;owner.Save();};body.Children.Add(tray);body.Children.Add(T("La croix masque la fenêtre. Pour arrêter les rappels et la capture rapide, choisissez Quitter dans le menu de l’icône.",11,Muted,new System.Windows.Thickness(0,0,0,16)));body.Children.Add(Btn("Sauvegarder tout mon espace",delegate{owner.ExportComplete();},true));body.Children.Add(Btn("Restaurer une sauvegarde complète",delegate{owner.RestoreComplete();}));body.Children.Add(T("Données, réglages, fichiers joints et MP3. Les dossiers du PC épinglés ne sont pas copiés. Sauvegarde non chiffrée : conservez-la dans un endroit privé.",11,Muted,new System.Windows.Thickness(0,10,0,16)));body.Children.Add(Btn("Quitter complètement Mon espace",delegate{owner.RequestQuit();},false,true));}
 internal void PreviewBackupSettings(string path){selected="Réglages";Refresh();Preview(path+"-sauvegardes.png");}
 internal void ResetAfterRestore(){selected="Aujourd’hui";openProject="";globalQuery="";globalKind="";projectFilter="Tous les projets";noteQuery="";showTrash=false;Refresh();}
}
